{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Norethisterone, a 4-en-3-one steroid, has absolute oral bioavailability of 47–73% (mean 64%) in women, supporting high F for the steroid-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Hydrocortisone, a polar corticosteroid, has absolute oral bioavailability of 0.88 (0.75–1.05) in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Levonorgestrel, a 4-en-3-one progestin, has a mean absolute oral bioavailability of 94% across three human studies, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Nomegestrol acetate, a steroidal progestin, has an absolute oral bioavailability of 63.4% in healthy young women, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Etonogestrel derived from desogestrel has an absolute oral bioavailability of 0.82 (0.76–0.88) in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Abiraterone acetate has an estimated absolute oral bioavailability below 10% in humans; this contradictory low-F example is less transferable because its low F is tied to poor solubility/prodrug characteristics and its structure is less similar to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C56"],
      "claim": "Anecortave desacetate showed low oral bioavailability in humans; this contradictory example is structurally more distant and does not override the consistent high-F pattern among closer steroidal analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a steroid 4-en-3-one with a metabolically protected pentafluoroethyl carbinol and an aryl methylsulfone. Most directly relevant steroidal analogues show absolute oral bioavailability well above 20%, often 60–100%. The two low-F examples are less similar and their low F is associated with specific prodrug/solubility or ocular-use liabilities. Therefore high F is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "Morgan similarities to evidence molecules are low (0.22–0.37), so transfer relies on shared steroid scaffold rather than close analogue matches.",
    "The effect of the 4-methylsulfonylphenyl and pentafluoroethyl carbinol substituents on absorption and first-pass metabolism is not directly covered by the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

